using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using System.Xml.Linq;using V15Voice;
public static class SubtitleQualityUiTests {
 static int count,code;static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}static void Check(bool b,string n){if(!b)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();f.Shown+=(s,e)=>{try{
 string folder=Path.Combine(Path.GetTempPath(),"v15_148_quality_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string media=Path.Combine(folder,"source.mp4");File.WriteAllText(media,"source fixture");Call(f,"AddSubtitleFiles",new object[]{new[]{media}});var jobs=(List<SubtitleJob>)F(f,"subtitleQueue");var j=jobs.Last();j.Document=new SubtitleDocument{Duration=8,Audit=new XElement("audit",new XElement("change",new XAttribute("removed","playing"))),Cues=new List<SubtitleCue>{new SubtitleCue{Start=0,End=2,Text="He was playing pool.",Info="Đã bỏ từ lặp"},new SubtitleCue{Start=2,End=4,Text="The next sentence.",Note="Chữ chạy nhanh"}}};j.Output=j.Document.ExportBeside(media);j.State=j.Document.CompletionState;Call(f,"RefreshSubtitleJobs");var grid=(DataGridView)F(f,"subtitleJobs");grid.CurrentCell=grid.Rows[grid.Rows.Count-1].Cells[0];Call(f,"SelectSubtitleJob");var review=(DataGridView)F(f,"subtitleGrid");Check(j.Document.ReviewCount==1&&j.State.Contains("cần duyệt"),"Exported file with pending review is not presented as clean");Check(review.Rows[0].DefaultCellStyle.BackColor==Color.AliceBlue&&review.Rows[1].DefaultCellStyle.BackColor==Color.LemonChiffon,"Automatic corrections and unresolved rows have distinct colours");review.CurrentCell=review.Rows[1].Cells[3];Call(f,"ApproveSubtitleCue");Check(j.Document.ReviewCount==0&&j.State=="Xong","Explicit review clears pending status");var stored=SubtitleDocument.Load(j.Result);Check(stored.Cues[1].Reviewed&&stored.Cues[0].Info=="Đã bỏ từ lặp"&&stored.Audit.Element("change").Attribute("removed").Value=="playing","Review, automatic correction and audit survive save/load");review.CurrentCell=review.Rows[1].Cells[3];review.Rows[1].Cells[3].Value="Changed after approval.";Call(f,"SaveSubtitleEdits");Check(!j.Document.Cues[1].Reviewed&&j.Document.ReviewCount==1&&j.State=="Đã sửa · chưa xuất","Editing invalidates approval and marks export stale");Check(!((bool)Call(f,"SubtitleCompleted",j)),"Unexported edits cannot be skipped as completed");Call(f,"ExportSubtitleEdits");Check(j.State.Contains("cần duyệt")&&File.ReadAllText(j.Output).Contains("Changed after approval."),"Export keeps review status and writes corrected words");j.Profile=(string)Call(f,"SubtitleProfile",j,"large-v3",false);Check(j.Profile!=(string)Call(f,"SubtitleProfile",j,"distil-large-v3",false),"Changing recognizer invalidates completed profile");Check(j.Profile!=(string)Call(f,"SubtitleProfile",j,"large-v3",true),"Changing subtitle layout invalidates completed profile");string old=Path.Combine(folder,"old.xml");File.WriteAllText(old,"<subtitles version='1.4.7' duration='8'><cue start='0' end='2'>Old result.</cue></subtitles>");var legacy=SubtitleDocument.Load(old);Check(legacy.Pipeline=="","Legacy output never acquires a new pipeline stamp by opening it");legacy.Save(old);Check(SubtitleDocument.Load(old).Pipeline=="","Saving legacy output preserves need for reprocessing");
 Console.WriteLine("TOTAL QUALITY UI "+count+" passed.");
 }catch(Exception x){Console.WriteLine(x);code=1;}finally{f.Close();}};Application.Run(f);Environment.Exit(code);}
}
